window.products.push({"id":174906,"name":"SleepJoy ViscoFresh Green Tea Memory Foam Pillow, Jumbo","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/91QfPgiDiKL._AC_SL1500_.jpg","description":"The SleepJoy High-Profile Green Tea Memory Foam Pillow is designed with soft, conforming, high-density memory foam that cradles the head and neck for superior comfort. The SleepJoy High-Profile Green Tea Memory Foam Pillow is made with plant based ingredients and contains green tea to neutralize foam odors and replace them with a fresh scent that fades over time. Allover ventilation and open cell construction allows for greater airflow, which creates a cooler, more hygienic sleeping environment. The Nano-Tex Coolest Comfort outer cover breathes and wicks away moisture and a zippered inner cover protects and increases the lifespan of the pillow; both covers are machine washable and dryer safe.","images":["https://m.media-amazon.com/images/I/91QfPgiDiKL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"SleepJoy","source_asin":"B076FFBW43","category_path":"Home & Kitchen"},"sku":"BM-174906","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B076FFBW43","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B076FFBW43","price_pending":true,"merchant_ready":false});
